CREATE TABLE IF NOT EXISTS events(id BIGINT AUTO_INCREMENT PRIMARY KEY,event_name VARCHAR(120) NOT NULL,description VARCHAR(1000),event_date DATE NOT NULL,venue VARCHAR(180) NOT NULL,capacity INT NOT NULL CHECK(capacity>0),active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS students(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,roll_number VARCHAR(40) NOT NULL UNIQUE,department VARCHAR(100) NOT NULL,year_of_study INT NOT NULL,phone VARCHAR(20),active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS registrations(id BIGINT AUTO_INCREMENT PRIMARY KEY,student_id BIGINT NOT NULL,event_id BIGINT NOT NULL,registration_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,status VARCHAR(30) DEFAULT 'REGISTERED',FOREIGN KEY(student_id) REFERENCES students(id),FOREIGN KEY(event_id) REFERENCES events(id),UNIQUE(student_id,event_id));
